function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 3;
  ctx.strokeStyle = 'black';
  ctx.fillStyle = 'black';
  // draw three circles
  ctx.beginPath();
  ctx.arc(W/2 - 100, H/2, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.fill();
  ctx.beginPath();
  ctx.arc(W/2, H/2, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.fill();
  ctx.beginPath();
  ctx.arc(W/2 + 100, H/2, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.fill();
  // draw nine lines
  for (let i = 0; i < 9; i++) {
    ctx.beginPath();
    ctx.moveTo(W/2 - 50 + i * 10, H/2 - 50 + Math.sin(t) * 20);
    ctx.lineTo(W/2 - 50 + i * 10, H/2 + 50 + Math.sin(t) * 20);
    ctx.stroke();
  }
  ctx.restore();
}
